#include <stdio.h>

int main(void) {
    int n;
    scanf("%d", &n);
    // count each ID, then find the most common
    return 0;
}

solution:
#include <stdio.h>

int main(void) {
    int n, count[100] = {0};
    scanf("%d", &n);
    for (int i = 0; i < n; i++) {
        int id;
        scanf("%d", &id);
        count[id]++;
    }
    int best = 0;
    for (int id = 1; id < 100; id++) {
        if (count[id] > count[best]) best = id;
    }
    printf("%d\n", best);
    return 0;
}
